.actions { margin-top: 14px; text-align: center; }
.tabs { display: flex; gap: 4px; margin-bottom: 12px; flex-wrap: wrap; }
.tabs a { padding: 7px 16px; border-radius: 6px; cursor: pointer; background: #fff; color: #606266; }
.tabs a.active { background: #409eff; color: #fff; }

/* 弹窗 */
.modal-mask { position: fixed; inset: 0; background: rgba(0,0,0,.45); z-index: 100; display: flex; align-items: flex-start; justify-content: center; overflow-y: auto; padding: 30px 16px; }
.modal { background: #f5f7fa; border-radius: 10px; width: 1080px; max-width: 96vw; padding: 20px 22px; }
.modal-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; font-size: 17px; }
